            continue;
        }
        if (!afterDoubleDash && command === "cd" && (arg === "-L" || arg === "-P")) {
            continue;
        }
        if (!afterDoubleDash && command === "cd" && arg === "-") {
            operands.push(arg);
            continue;
        }
        if (!afterDoubleDash && arg.startsWith("-")) {
            state.blocked = true;
            return false;
