const WORKER_CONFINEMENT = {
    enabled: true,
    permission: "allow" as const,
    resolveSymlinks: true,
};
const SETUP_BASH_TIMEOUT_SECONDS = 10 * 60;

function isWorkerPathAllowed(filePath: string | undefined, cwd: string): boolean {
