    const realCwd = options.realCwd;
    if (realCwd === null) {
        return true;
    }

    let current = resolvePath(p, cwd, home);

    while (true) {
        let stat: fs.Stats | undefined;
        try {
            stat = fs.lstatSync(current);
        } catch {
            stat = undefined;
        }

        if (stat) {
            let real: string;
            try {
                real = fs.realpathSync(current);
